    def get_table_result(self, job_id: str) -> list:
        import time
        while True:
            resp = self.textract.get_document_table_detection(JobId=job_id)
            if resp["JobStatus"] == "SUCCEEDED":
                # Convert AWS table JSON to simple list-of-lists structure
                tables = []
                for table in resp.get("Blocks", []):
                    if table["BlockType"] != "TABLE":
                        continue
                    rows = []
                    for row in table.get("Relationships", []):
                        if row["Type"] != "CHILD":
                            continue
                        cell_rows = []
                        for cell_id in row["Ids"]:
                            cell = next(
                                (b for b in resp["Blocks"] if b["Id"] == cell_id and b["BlockType"] == "CELL"),
                                None,
                            )
                            if cell:
                                cell_rows.append(
                                    {
                                        "Text": next(
                                            (
                                                b["Text"]
                                                for b in resp["Blocks"]
                                                if b.get("Relationships")
                                                and any(
                                                    r["Type"] == "CHILD"
                                                    and r["Ids"][0] == cell["Id"]
                                                    for r in b.get("Relationships", [])
                                                )
                                            ),
                                            "",
                                        ),
                                    }
                                )
                        rows.append(cell_rows)
                    tables.append(rows)
                return tables
            time.sleep(1)

